// Actual production native upgrade command, paused transaction; no PlayerPrefs writes.
if(!UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Play required");
var runtime=UnityEngine.Object.FindFirstObjectByType<EchoSphere.Runtime.EchoSphereRuntime>();var type=runtime.GetType();var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public;
string[] names={"_mainMenu","_levelUp","_choosingEvolution","_gameOver","_follow","_paused","_xp","_xpRequired","_levelUpLockChoiceKey","_levelUpSpherePity","_levelUpAbilityPity"};var saved=names.Select(n=>type.GetField(n,flags).GetValue(runtime)).ToArray();bool oldPause=UnityEditor.EditorApplication.isPaused;
var levels=(Dictionary<EchoSphere.Core.RunUpgradeKind,int>)type.GetField("_abilityLevels",flags).GetValue(runtime);var oldLevels=levels.ToArray();var choices=(List<EchoSphere.Core.RunUpgradeChoice>)type.GetField("_levelUpChoices",flags).GetValue(runtime);var oldChoices=choices.ToArray();var recent=(List<string>)type.GetField("_recentUpgradeChoiceKeys",flags).GetValue(runtime);var oldRecent=recent.ToArray();var failures=new List<string>();int cases=0;
void Set(string name,object value){var field=type.GetField(name,flags);field.SetValue(runtime,value==null||field.FieldType.IsInstanceOfType(value)?value:System.Convert.ChangeType(value,field.FieldType));}
try{UnityEditor.EditorApplication.isPaused=true;Set("_mainMenu",false);Set("_gameOver",false);Set("_follow",false);Set("_choosingEvolution",false);Set("_xp",0);Set("_xpRequired",1);Set("_levelUpLockChoiceKey",null);
foreach(var kind in new[]{EchoSphere.Core.RunUpgradeKind.Resonance,EchoSphere.Core.RunUpgradeKind.CritPower,EchoSphere.Core.RunUpgradeKind.ProjectileSpeed,EchoSphere.Core.RunUpgradeKind.Fortune})for(int current=0;current<7;current++){levels[kind]=current;Set("_levelUp",true);Set("_paused",true);choices.Clear();choices.Add(new EchoSphere.Core.RunUpgradeChoice(kind,EchoSphere.Core.SphereId.Standard,current,current+1,"fixture","fixture"));type.GetMethod("PickNativeUpgrade",flags).Invoke(runtime,new object[]{0});cases++;if(!levels.TryGetValue(kind,out var actual)||actual!=current+1)failures.Add(kind+" "+current+" -> "+actual+" expected "+(current+1));if((bool)type.GetField("_levelUp",flags).GetValue(runtime)||choices.Count!=0)failures.Add(kind+" did not consume choice");}
}finally{levels.Clear();foreach(var pair in oldLevels)levels[pair.Key]=pair.Value;choices.Clear();choices.AddRange(oldChoices);recent.Clear();recent.AddRange(oldRecent);for(int i=0;i<names.Length;i++)Set(names[i],saved[i]);UnityEditor.EditorApplication.isPaused=oldPause;}
return new{cases,failures,status=failures.Count==0?"PASS":"FAIL",scope="Actual PickNativeUpgrade level storage and choice consumption; no gameplay formula assumption, no evolution parity claim, dictionaries/flags restored"};
